&quot;); 5、建立HTTPS代理连接并握手 12345final String serverLocation = proxyArgLine.split(&quot; &quot;)[1]; final String serverIp = serverLocation.split(&quot;:&quot;)[0]; final String serverPort = serverLocation.split(&quot;:&quot;)[1];SSLSocket clientSslSocket = (SSLSocket) SimpleHttpProxyServer.SSL_CONTEXT.getSocketFactory().createSocket(clientSocket, clientSocket.getInputStream(), true); clientSslSocket.startHandshake(); 6、向客户端发送连接已经建立的消息 1clientSocket.getOutputStream().write(&quot;HTTP/1.1 200 Connection Established

&quot;.getBytes()); 7、使用SSLContext.getSocketFactory()将Socket升级为SSL连接并握手 12SSLSocket serverSslSocket = (SSLSocket)SimpleHttpProxyServer.TRUST_ALL_SSL_SOCKET_FACTORY.createSocket(serverIp, Convert.toInt(serverPort)); serverSslSocket.startHandshake(); 8、读取HTTPS Request 1String content = new String(IOUtil.readAllBytes(clientSslSocket.getInputStream())); 9、转发HTTPS Request 1serverSslSocket.getOutputStream().write(content.getBytes()); 10、转发HTTPS Response 1clientSslSocket.getOutputStream().write(IOUtil.readAllBytes(serverSslSocket.getInputStream()));
